INSERT INTO `wp_options` VALUES (2911,'smoothmigration_htaccess_rules','\n# Serve WebP images when supported\n<IfModule mod_rewrite.c>\n    RewriteEngine On\n    \n    # Check for WebP support and file existence\n    RewriteCond %{HTTP_ACCEPT} image/webp\n    RewriteCond %{REQUEST_FILENAME} \\.(jpe?g|png)$\n    RewriteCond %{REQUEST_FILENAME}\\.webp -f\n    RewriteRule (.+)\\.(jpe?g|png)$ $1.$2.webp [T=image/webp,E=accept:1,L]\n    \n    # Check for AVIF support and file existence\n    RewriteCond %{HTTP_ACCEPT} image/avif\n    RewriteCond %{REQUEST_FILENAME} \\.(jpe?g|png)$\n    RewriteCond %{REQUEST_FILENAME}\\.avif -f\n    RewriteRule (.+)\\.(jpe?g|png)$ $1.$2.avif [T=image/avif,E=accept:1,L]\n</IfModule>\n\n# Set proper MIME types\n<IfModule mod_mime.c>\n    AddType image/webp .webp\n    AddType image/avif .avif\n</IfModule>\n\n# Add Vary header for proper caching\n<IfModule mod_headers.c>\n    <FilesMatch \"\\.(jpe?g|png)$\">\n        Header append Vary Accept\n    </FilesMatch>\n</IfModule>\n','auto');
