\r\n.forminator-input:hover, .forminator-textarea:hover, .select2-selection:hover{\r\n  border-color: #3399ff;\r\n  background-color: #f0f8ff;\r\n}\r\n\r\n.forminator-input:focus, .forminator-textarea:focus, .select2-selection:focus{\r\n  border-color: #0077ff;\r\n  background-color: white;\r\n  box-shadow: 0 0 0 4px rgba(0, 119, 255, 0.15);\r\n}\r\n\r\n.forminator-textarea {\r\n  min-height: 120px;\r\n  resize: vertical;\r\n}\r\n\r\nbutton,\r\ninput[type=\"submit\"] {\r\n  width: 100%;\r\n  padding: 14px;\r\n  margin-top: 16px;\r\n  background: linear-gradient(to right, #3399ff, #0077ff);\r\n  color: white;\r\n  border: none;\r\n  border-radius: 12px;\r\n  font-size: 17px;\r\n  font-weight: bold;\r\n  cursor: pointer;\r\n  transition: background 0.3s ease, transform 0.2s ease;\r\n}\r\n\r\nbutton:hover,\r\ninput[type=\"submit\"]:hover {\r\n  background: linear-gradient(to right, #0077ff, #005fcc);\r\n  transform: translateY(-2px);\r\n  box-shadow: 0 6px 20px rgba(0, 102, 255, 0.3);\r\n}\r\n\r\nbutton:focus,\r\ninput[type=\"submit\"]:focus {\r\n  outline: none;\r\n  box-shadow: 0 0 0 4px rgba(0, 119, 255, 0.2);\r\n}\r\n\r\n::placeholder {\r\n  color: #99bce3;\r\n  opacity: 1;\r\n  font-style: italic;\r\n}\r\n\r\n.forminator-label {\r\n  display: block;\r\n  margin-top: 0px;\r\n  margin-bottom: 0px;\r\n  color: #003366;\r\n  font-size:1rem;\r\n  font-weight: 600;\r\n}\";s:17:\"field-image-width\";s:2:\"70\";}s:9:\"client_id\";N;s:22:\"integration_conditions\";a:0:{}s:9:\"behaviors\";a:1:{i:0;a:10:{s:4:\"slug\";s:18:\"behavior-1234-4567\";s:5:\"label\";s:0:\"\";s:14:\"autoclose-time\";s:1:\"5\";s:9:\"autoclose\";s:4:\"true\";s:6:\"newtab\";s:7:\"sametab\";s:16:\"thankyou-message\";s:57:\"Thank you for contacting us, we will be in touch shortly.\";s:22:\"email-thankyou-message\";s:0:\"\";s:23:\"manual-thankyou-message\";s:0:\"\";s:20:\"submission-behaviour\";s:18:\"behaviour-thankyou\";s:12:\"redirect-url\";s:0:\"\";}}s:13:\"notifications\";a:1:{i:0;a:9:{s:4:\"slug\";s: