INSERT INTO `wp_postmeta` VALUES (5306,6543,'_service_affiliate_url','https://my.thinkhomewise.com/p/smoothmigration');
INSERT INTO `wp_postmeta` VALUES (5307,6543,'_service_quick_view','Multi-currency account with real exchange rates and transparent fees. • Hold 40+ currencies • International transfers at mid-market rates • Debit card for global spending. Trusted by 16M+ customers worldwide. Manage your cross-border finances with ease.');
INSERT INTO `wp_postmeta` VALUES (5308,6580,'_service_quick_view','Stay connected in 200+ countries with eSIM data plans from $4.50. • No physical SIM card needed • Install and activate in minutes • Avoid roaming charges. Trusted by 5M+ travelers worldwide. Connect the moment you land.');
INSERT INTO `wp_postmeta` VALUES (5309,6548,'_service_affiliate_url','https://www.nbc.ca/personal/accounts/newcomers/moneysense-offer.html');
INSERT INTO `wp_postmeta` VALUES (5310,6548,'_service_quick_view','One of Canada\'s 6 major banks, established in 1859. • Newcomer-focused account packages • Full banking, credit, and investment services • Branch network across Canada. 165+ years of financial stability. Start your Canadian financial journey securely.');
INSERT INTO `wp_postmeta` VALUES (5311,6584,'_service_affiliate_url','https://fxo.co/1313391/covermore');
INSERT INTO `wp_postmeta` VALUES (5312,6584,'_service_quick_view','Global travel insurance covering medical emergencies, trip cancellations, and lost luggage. • 24/7 emergency assistance in 40+ languages • Coverage from $25 for short trips • Plans for individuals and families. Decades of experience worldwide. Travel with confidence during your relocation.');
INSERT INTO `wp_postmeta` VALUES (5313,6596,'_service_affiliate_url','https://www.squareone.ca/smg');
INSERT INTO `wp_postmeta` VALUES (5314,6596,'_service_quick_view','Customizable home, tenant, and condo insurance fully online. • Choose only what you need • Instant quotes and digital management • No hidden fees or unnecessary extras. Award-winning digital insurance in Canada. Protect your new home affordably.');
INSERT INTO `wp_postmeta` VALUES (5315,6589,'_service_affiliate_url','https://www.petsplusus.com/partner/smoothmigration');
INSERT INTO `wp_postmeta` VALUES (5316,6589,'_service_quick_view','Pet insurance covering accidents and illnesses with flexible plans. • Direct vet payment options available • Monthly premiums from $29 • Coverage for cats, dogs, and exotics. Trusted by 100,000+ Canadian pet owners. Keep your furry family protected too.');
INSERT INTO `wp_postmeta` VALUES (5317,6612,'_service_affiliate_url','https://www.expatride.com/smooth-migration/');
INSERT INTO `wp_postmeta` VALUES (5318,6612,'_service_quick_view','Vehicle rentals and leases for expats without local credit history. • Short and long-term options • Insurance and registration assistance included • Chauffeur services available. Global expat mobility specialists. Get mobile within 48 hours of arrival.');
INSERT INTO `wp_postmeta` VALUES (5319,6566,'_service_quick_view','Wise is a financial technology company that\nprovides online money transfer services and a multi-currency account for\nindividuals and businesses to send, spend, and receive money\ninternationally at low fees and the mid-market exchange rate. • We recommend Wise for its transparency, speed, and...');
INSERT INTO `wp_postmeta` VALUES (5320,6559,'_service_quick_view','Send money to 170+ countries in minutes with guaranteed delivery. • Bank deposits, cash pickups, and mobile wallets • Low fees and competitive rates • On-time delivery or fee refund. Trusted by 5M+ customers globally. Stay financially connected during your move.');
INSERT INTO `wp_postmeta` VALUES (5321,6572,'_service_quick_view','International money transfers with live exchange rates and transparent fees. • Real-time currency tracking • Bank deposits or cash pickup • Transfer monitoring tools. 30+ years as trusted currency experts. Move money confidently across borders.');
INSERT INTO `wp_postmeta` VALUES (5322,6603,'_service_affiliate_url','https://www.expertsinmoving.com/?so=a&ca=8ddabfceef8192200632f66a00293f9c');
INSERT INTO `wp_postmeta` VALUES (5323,6603,'_service_quick_view','Compare moving companies with verified reviews and get up to 5 free quotes. • International and domestic moves • User reviews and ratings • Free quote comparison service. 250,000+ moves facilitated worldwide. Find reliable movers stress-free.');
INSERT INTO `wp_postmeta` VALUES (5324,6553,'_service_affiliate_url','https://partners.ownr.co/dkx2ast7r3id');
INSERT INTO `wp_postmeta` VALUES (5325,6553,'_service_quick_view','Incorporate your Canadian business online in 10 minutes. • Federal and provincial registration • Legal document creation • Automated compliance filings. Backed by RBC and trusted by 50,000+ entrepreneurs. Launch your business from day one.');
