INSERT INTO `wp_posts` VALUES (83,1,'2025-07-02 22:58:55','2025-07-02 22:58:55','<section class=\"py-5\"><div class=\"container\"><div class=\"row\"><div class=\"col-lg-5 mb-4\"><h2 class=\"fw-bold mb-3\">Get in Touch</h2><p>Questions, comments, or ready to start your relocation? Our advisors are here Monday–Friday&nbsp;9:00-17:00 (GMT-5).</p><ul class=\"list-unstyled\"><li class=\"mb-2\"><i class=\"fas fa-phone-alt text-primary me-2\"></i><strong>+1&nbsp;(555)&nbsp;123-4567</strong></li><li class=\"mb-2\"><i class=\"fas fa-envelope text-primary me-2\"></i><a href=\"mailto:hello@example.com\">hello@example.com</a></li><li><i class=\"fas fa-map-marker-alt text-primary me-2\"></i>123&nbsp;Migration Ave, Suite&nbsp;400<br>Global City, GC&nbsp;12345</li></ul></div><div class=\"col-lg-7\"><h2 class=\"fw-bold mb-3\">Send a Message</h2><!-- Replace with contact-form plugin shortcode if available --><form class=\"row g-3\" id=\"demo-contact\"><div class=\"col-md-6\"><input type=\"text\" class=\"form-control\" placeholder=\"Name\" required></div><div class=\"col-md-6\"><input type=\"email\" class=\"form-control\" placeholder=\"Email\" required></div><div class=\"col-12\"><textarea class=\"form-control\" rows=\"4\" placeholder=\"Message\" required></textarea></div><div class=\"col-12\"><button class=\"btn btn-primary\" type=\"submit\">Submit</button></div></form><div class=\"alert alert-success d-none mt-3\" id=\"demo-contact-success\">Thank you! We will get back to you shortly.</div></div></div></div></section>','Contact','','inherit','closed','closed','','75-revision-v1','','','2025-07-02 22:58:55','2025-07-02 22:58:55','',75,'http://wp-smooth-demo.local/?p=83',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (84,1,'2025-07-02 22:58:55','2025-07-02 22:58:55','<section class=\"py-5\"><div class=\"container\"><h2 class=\"fw-bold mb-4\">Latest Updates</h2><article class=\"mb-5\"><h5 class=\"fw-bold\">Smooth Migration Launches Partnership with Discover Cars</h5><p class=\"text-muted small mb-1\">02&nbsp;July&nbsp;2025</p><p>We are excited to announce a new collaboration that gives our clients discounted car rentals in over 150&nbsp;countries. Members can access the promo code inside their dashboard.</p><a class=\"btn btn-sm btn-outline-primary\" href=\"#\">Read More</a></article><article><h5 class=\"fw-bold\">Moving to Canada? 5 Banking Tips for Newcomers</h5><p class=\"text-muted small mb-1\">21&nbsp;June&nbsp;2025</p><p>Opening a bank account before you arrive saves time and helps build your credit history faster. Here are five things to know before submitting your application.</p><a class=\"btn btn-sm btn-outline-primary\" href=\"#\">Read More</a></article></div></section>','News','','inherit','closed','closed','','74-revision-v1','','','2025-07-02 22:58:55','2025-07-02 22:58:55','',74,'http://wp-smooth-demo.local/?p=84',0,'revision','',0);
