INSERT INTO `wp_posts` VALUES (295,0,'2025-07-18 00:02:17','2025-07-18 00:02:17','<section class=\"py-5\"><div class=\"container\"><div class=\"row\"><div class=\"col-lg-5 mb-4\"><h2 class=\"fw-bold mb-3\">Get in Touch</h2><p>Questions, comments, or ready to start your relocation? Our advisors are here Monday–Friday&nbsp;9:00-17:00 (GMT-5).</p><ul class=\"list-unstyled\"><li class=\"mb-2\"><i class=\"fas fa-phone-alt text-primary me-2\"></i><strong>+1&nbsp;(555)&nbsp;123-4567</strong></li><li class=\"mb-2\"><i class=\"fas fa-envelope text-primary me-2\"></i><a href=\"mailto:hello@example.com\">hello@example.com</a></li><li><i class=\"fas fa-map-marker-alt text-primary me-2\"></i>123&nbsp;Migration Ave, Suite&nbsp;400<br>Global City, GC&nbsp;12345</li></ul></div><div class=\"col-lg-7\"><h2 class=\"fw-bold mb-3\">Send a Message</h2><!-- Replace with contact-form plugin shortcode if available --><div class=\"col-md-6\"></div><div class=\"col-md-6\"></div><div class=\"col-12\"><textarea class=\"form-control\" rows=\"4\"></textarea></div><div class=\"col-12\"><button class=\"btn btn-primary\" type=\"submit\">Submit</button></div><div class=\"alert alert-success d-none mt-3\" id=\"demo-contact-success\">Thank you! We will get back to you shortly.</div></div></div></div></section>','Contact','','inherit','closed','closed','','75-revision-v1','','','2025-07-18 00:02:17','2025-07-18 00:02:17','',75,'https://wp-smooth-demo.local/?p=295',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (296,0,'2025-07-18 00:02:17','2025-07-18 00:02:17','<!-- wp:html -->\n<!-- Hero Section -->\n<section class=\"hero text-center text-white d-flex align-items-center justify-content-center\">\n  <div class=\"hero-content w-100\">\n    <div class=\"container fade-in-up\">\n      <h1 class=\"display-4 fw-bold\">Your Seamless Global Relocation Starts Here</h1>\n      <p class=\"lead\">From the UK, USA, South Africa, or Canada, Smooth Migration is your trusted partner for a stress-free move. We handle the details, so you can focus on your new beginning.</p>\n      <div class=\"d-flex gap-3 justify-content-center flex-wrap mt-4\">\n        <a href=\"/contact\" class=\"btn btn-primary btn-lg\">Start Your Journey</a>\n        <a href=\"/services\" class=\"btn btn-outline-light btn-lg\">Explore Our Services</a>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- \"Who We Are\" Section -->\n<section class=\"py-5\">\n  <div class=\"container\">\n    <div class=\"row align-items-center\">\n      <div class=\"col-lg-6\">\n        <h2 class=\"display-5 fw-bold\">Who We Are at Smooth Migration</h2>\n        <p class=\"lead text-muted\">We are a team of relocation experts dedicated to making your international move as smooth and seamless as possible. With round-the-clock assistance and deep technical expertise, we navigate the complexities of relocation so you don\'t have to.</p>\n        <p>Our global network of top-tier partners ensures that you receive the best service in every aspect of your move, from finding a home to settling into your new community. We\'re with you every step of the way.</p>\n      </div>\n      <div class=\"col-lg-6 text-center\">\n        <img src=\"https://wp-smooth-demo.local/wp-content/themes/smoothmigration/assets/images/smooth-migration-logo.png\" alt=\"Smooth Migration\" class=\"img-fluid rounded-3\" style=\"max-height: 250px;\">\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- \"How It Works\" Section -->\n<section class=\"py-5 bg-light\">\n    <div class=\"container\">\n        <div class=\"text-center mb-5\">\n            <h2 class=\"display-5 fw-bold\">Your Relocation Journey, Simplified</h2>\n            <p class=\"lead text-muted\">We follow a proven process to ensure a smooth transition for you and your family.</p>\n        </div>\n        <div class=\"row text-center\">\n            <div class=\"col-md-4\">\n                <div class=\"p-4\">\n                    <div class=\"service-icon mx-auto mb-3\">\n                        <i class=\"fas fa-comments\"></i>\n                    </div>\n                    <h4>1. Consultation</h4>\n                    <p class=\"text-muted\">We start with a detailed consultation to understand your unique needs and create a customized relocation plan.</p>\n                </div>\n            </div>\n            <div class=\"col-md-4\">\n                <div class=\"p-4\">\n                    <div class=\"service-icon mx-auto mb-3\">\n                        <i class=\"fas fa-cogs\"></i>\n                    </div>\n                    <h4>2. Planning & Coordination</h4>\n                    <p class=\"text-muted\">We handle all the logistics, from visa applications to finding the perfect home, coordinating with our global partners.</p>\n                </div>\n            </div>\n            <div class=\"col-md-4\">\n                <div class=\"p-4\">\n                    <div class=\"service-icon mx-auto mb-3\">\n                        <i class=\"fas fa-handshake\"></i>\n                    </div>\n                    <h4>3. Arrival & Settling In</h4>\n                    <p class=\"text-muted\">We provide on-the-ground support to help you settle into your new life, from opening a bank account to finding the best schools.</p>\n                </div>\n            </div>\n        </div>\n    </div>\n</section>\n\n<!-- Services Section -->\n<section class=\"py-5\">\n  <div class=\"container\">\n    <div class=\"text-center mb-5\">\n      <h2 class=\"display-5 fw-bold\">Everything You Need for a Smooth Move</h2>\n      <p class=\"lead text-muted\">Our comprehensive services are designed to cover every aspect of your relocation.</p>\n    </div>\n    <div class=\"row g-4\">\n      <div class=\"col-lg-4 col-md-6\">\n        <div class=\"service-card\">\n          <div class=\"service-icon mx-auto\">\n            <i class=\"fas fa-home\"></i>\n          </div>\n          <h4>Realtor Locator</h4>\n          <p class=\"text-muted\">Find the perfect home with our network of trusted real estate agents in your new city.</p>      \n          <a href=\"/services/realtor-locator\" class=\"btn btn-outline-primary\">View Programs</a>\n        </div>\n      </div>\n      <div class=\"col-lg-4 col-md-6\">\n        <div class=\"service-card\">\n          <div class=\"service-icon mx-auto\">\n            <i class=\"fas fa-university\"></i>\n          </div>\n          <h4>Banking Services</h4>\n          <p class=\"text-muted\">Set up your finances with ease, from opening a bank account to securing a mortgage.</p>        \n          <a href=\"/services/banking-services\" class=\"btn btn-outline-primary\">View Programs</a>\n        </div>\n      </div>\n      <div class=\"col-lg-4 col-md-6\">\n        <div class=\"service-card\">\n          <div class=\"service-icon mx-auto\">\n            <i class=\"fas fa-shield-alt\"></i>\n          </div>\n          <h4>Insurance</h4>\n          <p class=\"text-muted\">Protect yourself and your family with comprehensive health, travel, and property insurance.</p>\n          <a href=\"/services/insurance\" class=\"btn btn-outline-primary\">View Programs</a>\n        </div>\n      </div>\n      <div class=\"col-lg-4 col-md-6\">\n        <div class=\"service-card\">\n          <div class=\"service-icon mx-auto\">\n            <i class=\"fas fa-exchange-alt\"></i>\n          </div>\n          <h4>International Transfers</h4>\n          <p class=\"text-muted\">Transfer money securely and efficiently with competitive exchange rates.</p>\n          <a href=\"/services/international-transfers\" class=\"btn btn-outline-primary\">View Programs</a>\n        </div>\n      </div>\n      <div class=\"col-lg-4 col-md-6\">\n        <div class=\"service-card\">\n          <div class=\"service-icon mx-auto\">\n            <i class=\"fas fa-mobile-alt\"></i>\n          </div>\n          <h4>Mobile & Cellular Plans</h4>\n          <p class=\"text-muted\">Stay connected with a local phone number and data plan from the moment you arrive.</p>      \n          <a href=\"/services/mobile-and-cellular-plans\" class=\"btn btn-outline-primary\">View Programs</a>\n        </div>\n      </div>\n      <div class=\"col-lg-4 col-md-6\">\n        <div class=\"service-card\">\n          <div class=\"service-icon mx-auto\">\n            <i class=\"fas fa-car\"></i>\n          </div>\n          <h4>Vehicles</h4>\n          <p class=\"text-muted\">Arrange for a car rental, lease, or purchase to get you on the road in your new country.</p>\n          <a href=\"/services/vehicles\" class=\"btn btn-outline-primary\">View Programs</a>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- Testimonials Section -->\n<section class=\"py-5 bg-light\">\n  <div class=\"container\">\n    <div class=\"text-center mb-5\">\n      <h2 class=\"display-5 fw-bold\">Success Stories from Our Clients</h2>\n      <p class=\"lead text-muted\">See what our clients have to say about their experience with Smooth Migration.</p>\n    </div>\n    <div class=\"row\">\n      <div class=\"col-lg-6\">\n        <div class=\"testimonial-card\">\n          <p class=\"testimonial-text\">\"The team at Smooth Migration made our move from the UK to Canada an absolute breeze. Their attention to detail and personalized service were exceptional. We couldn\'t have done it without them.\"</p>\n          <div class=\"testimonial-author\">\n            <strong>The Williams Family</strong><br>\n            <small class=\"text-muted\">Relocated from London to Toronto</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"col-lg-6\">\n        <div class=\"testimonial-card\">\n          <p class=\"testimonial-text\">\"As a professional relocating from the USA to South Africa, I was impressed with the technical expertise and round-the-clock support I received from Smooth Migration. They are true professionals.\"</p>\n          <div class=\"testimonial-author\">\n            <strong>David Chen</strong><br>\n            <small class=\"text-muted\">Relocated from New York to Cape Town</small>\n          </div>\n        </div>\n      </div>\n    </div>\n    <div class=\"text-center mt-4\">\n      <a href=\"/testimonials\" class=\"btn btn-primary\">Read More Success Stories</a>\n    </div>\n  </div>\n</section>\n\n<!-- Call to Action Section -->\n<section class=\"py-5 text-center text-white\" style=\"background: var(--primary-dark);\">\n    <div class=\"container\">\n        <h2 class=\"display-5 fw-bold\">Ready to Start Your Relocation Journey?</h2>\n        <p class=\"lead\">Let\'s make your move a smooth one. Contact us today for a free consultation.</p>\n        <a href=\"/contact\" class=\"btn btn-accent btn-lg\" style=\"background: var(--accent-color); color: var(--text-dark);\">Get Your Free Consultation</a>\n    </div>\n</section>\n<!-- /wp:html -->','Home','','publish','closed','closed','','home','','','2025-07-19 23:43:21','2025-07-19 23:43:21','',0,'https://wp-smooth-demo.local/home/',0,'page','',0);
INSERT INTO `wp_posts` VALUES (297,2,'2025-07-18 00:02:22','2025-07-18 00:02:22','<section class=\"py-5\"><div class=\"container\"><div class=\"row\"><div class=\"col-lg-5 mb-4\"><h2 class=\"fw-bold mb-3\">Get in Touch</h2><p>Questions, comments, or ready to start your relocation? Our advisors are here Monday–Friday&nbsp;9:00-17:00 (GMT-5).</p><ul class=\"list-unstyled\"><li class=\"mb-2\"><i class=\"fas fa-phone-alt text-primary me-2\"></i><strong>+1&nbsp;(555)&nbsp;123-4567</strong></li><li class=\"mb-2\"><i class=\"fas fa-envelope text-primary me-2\"></i><a href=\"mailto:hello@example.com\">hello@example.com</a></li><li><i class=\"fas fa-map-marker-alt text-primary me-2\"></i>123&nbsp;Migration Ave, Suite&nbsp;400<br>Global City, GC&nbsp;12345</li></ul></div><div class=\"col-lg-7\"><h2 class=\"fw-bold mb-3\">Send a Message</h2><!-- Replace with contact-form plugin shortcode if available --><form class=\"row g-3\" id=\"demo-contact\"><div class=\"col-md-6\"><input type=\"text\" class=\"form-control\" placeholder=\"Name\" required></div><div class=\"col-md-6\"><input type=\"email\" class=\"form-control\" placeholder=\"Email\" required></div><div class=\"col-12\"><textarea class=\"form-control\" rows=\"4\" placeholder=\"Message\" required></textarea></div><div class=\"col-12\"><button class=\"btn btn-primary\" type=\"submit\">Submit</button></div></form><div class=\"alert alert-success d-none mt-3\" id=\"demo-contact-success\">Thank you! We will get back to you shortly.</div></div></div></div></section>','Contact','','inherit','closed','closed','','75-revision-v1','','','2025-07-18 00:02:22','2025-07-18 00:02:22','',75,'https://stormy-support.localsite.io/?p=297',0,'revision','',0);
