INSERT INTO `wp_posts` VALUES (300,0,'2025-07-18 00:03:45','2025-07-18 00:03:45','<!-- wp:html --><!-- Hero Section -->\r\n<section class=\"hero text-center text-white d-flex align-items-center justify-content-center\">\r\n  <div class=\"hero-content w-100\">\r\n    <div class=\"container fade-in-up\">\r\n      <h1 class=\"display-4 fw-bold\">Global Relocation Services</h1>\r\n      <p class=\"lead\">Specialised global relocation services with over 50 years of experience across 5 continents</p>\r\n      <div class=\"d-flex gap-3 justify-content-center flex-wrap mt-4\">\r\n        <a href=\"/contact\" class=\"btn btn-primary btn-lg\">Get Started</a>\r\n        <a href=\"/services\" class=\"btn btn-outline-light btn-lg\">Our Services</a>\r\n      </div>\r\n      <div class=\"d-flex gap-2 justify-content-center flex-wrap mt-3\">\r\n        <a href=\"/about-us\" class=\"btn btn-outline-light\">About Us</a>\r\n        <a href=\"/news\" class=\"btn btn-outline-light\">News</a>\r\n        <a href=\"/legal-disclaimer\" class=\"btn btn-outline-light\">Legal Disclaimer</a>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- Stats Section -->\r\n<section class=\"stats-section\">\r\n  <div class=\"container\">\r\n    <div class=\"row\">\r\n      <div class=\"col-md-3 col-6\">\r\n        <div class=\"stat-item fade-in-up\">\r\n          <span class=\"stat-number\">25+</span>\r\n          <span class=\"stat-label\">Years of Trust</span>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-md-3 col-6\">\r\n        <div class=\"stat-item fade-in-up\">\r\n          <span class=\"stat-number\">20+</span>\r\n          <span class=\"stat-label\">Global Partners</span>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-md-3 col-6\">\r\n        <div class=\"stat-item fade-in-up\">\r\n          <span class=\"stat-number\">5</span>\r\n          <span class=\"stat-label\">Continents</span>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-md-3 col-6\">\r\n        <div class=\"stat-item fade-in-up\">\r\n          <span class=\"stat-number\">50+</span>\r\n          <span class=\"stat-label\">Years Experience</span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- Services Section -->\r\n<section class=\"py-5 bg-light\">\r\n  <div class=\"container\">\r\n    <div class=\"text-center mb-5\">\r\n      <h2 class=\"display-5 fw-bold\">Services We Provide</h2>\r\n      <p class=\"lead text-muted\">Comprehensive relocation solutions tailored to your needs</p>\r\n    </div>\r\n    <div class=\"row g-4\">\r\n      <div class=\"col-lg-4 col-md-6\">\r\n        <div class=\"service-card\">\r\n          <div class=\"service-icon mx-auto\">\r\n            <i class=\"fas fa-home\"></i>\r\n          </div>\r\n          <h4>Realtor Locator</h4>\r\n          <p class=\"text-muted\">Get qualified realtors in your chosen location with useful local knowledge.</p>\r\n          <a href=\"/services/realtor-locator\" class=\"btn btn-outline-primary\">View Programs</a>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-lg-4 col-md-6\">\r\n        <div class=\"service-card\">\r\n          <div class=\"service-icon mx-auto\">\r\n            <i class=\"fas fa-university\"></i>\r\n          </div>\r\n          <h4>Banking Services</h4>\r\n          <p class=\"text-muted\">From your first bank account setup to business accounts, we have options.</p>\r\n          <a href=\"/services/banking-services\" class=\"btn btn-outline-primary\">View Programs</a>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-lg-4 col-md-6\">\r\n        <div class=\"service-card\">\r\n          <div class=\"service-icon mx-auto\">\r\n            <i class=\"fas fa-shield-alt\"></i>\r\n          </div>\r\n          <h4>Insurance</h4>\r\n          <p class=\"text-muted\">Comprehensive coverage from travel to private health and pet insurance.</p>\r\n          <a href=\"/services/insurance\" class=\"btn btn-outline-primary\">View Programs</a>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-lg-4 col-md-6\">\r\n        <div class=\"service-card\">\r\n          <div class=\"service-icon mx-auto\">\r\n            <i class=\"fas fa-exchange-alt\"></i>\r\n          </div>\r\n          <h4>International Transfers</h4>\r\n          <p class=\"text-muted\">Easy and convenient money transfers for your global financial needs.</p>\r\n          <a href=\"/services/international-transfers\" class=\"btn btn-outline-primary\">View Programs</a>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-lg-4 col-md-6\">\r\n        <div class=\"service-card\">\r\n          <div class=\"service-icon mx-auto\">\r\n            <i class=\"fas fa-mobile-alt\"></i>\r\n          </div>\r\n          <h4>Mobile & Cellular Plans</h4>\r\n          <p class=\"text-muted\">Top quality suppliers for cellular and data. Get your local number quickly!</p>\r\n          <a href=\"/services/mobile-and-cellular-plans\" class=\"btn btn-outline-primary\">View Programs</a>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-lg-4 col-md-6\">\r\n        <div class=\"service-card\">\r\n          <div class=\"service-icon mx-auto\">\r\n            <i class=\"fas fa-car\"></i>\r\n          </div>\r\n          <h4>Vehicles</h4>\r\n          <p class=\"text-muted\">Rental, leasing and buying options for vehicles, catering to your needs.</p>\r\n          <a href=\"/services/vehicles\" class=\"btn btn-outline-primary\">View Programs</a>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- Testimonials Section -->\r\n<section class=\"py-5\">\r\n  <div class=\"container\">\r\n    <div class=\"text-center mb-5\">\r\n      <h2 class=\"display-5 fw-bold\">What Clients Say About Us</h2>\r\n      <p class=\"lead text-muted\">Trusted by millions worldwide</p>\r\n    </div>\r\n    <div class=\"row\">\r\n      <div class=\"col-lg-6\">\r\n        <div class=\"testimonial-card\">\r\n          <p class=\"testimonial-text\">\"The team took the stress out of moving overseas. Professional, friendly, and always one step ahead.\"</p>\r\n          <div class=\"testimonial-author\">\r\n            <strong>Alex Johnson</strong><br>\r\n            <small class=\"text-muted\">Marketing Manager</small>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-lg-6\">\r\n        <div class=\"testimonial-card\">\r\n          <p class=\"testimonial-text\">\"Outstanding service from start to finish. They handled every detail so I could focus on my new role.\"</p>\r\n          <div class=\"testimonial-author\">\r\n            <strong>Jamie Lee</strong><br>\r\n            <small class=\"text-muted\">Software Engineer</small>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section><!-- /wp:html -->','Home','','inherit','closed','closed','','296-revision-v1','','','2025-07-18 00:03:45','2025-07-18 00:03:45','',296,'https://wp-smooth-demo.local/?p=300',0,'revision','',0);
