INSERT INTO `wp_posts` VALUES (384,0,'2025-07-19 22:19:10','2025-07-19 22:19:10','<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|70\",\"bottom\":\"var:preset|spacing|70\"}}},\"layout\":{\"type\":\"constrained\"}} -->\r\n<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--70);padding-bottom:var(--wp--preset--spacing--70)\">\r\n    <!-- wp:columns {\"verticalAlignment\":\"top\",\"align\":\"wide\"} -->\r\n    <div class=\"wp-block-columns alignwide are-vertically-aligned-top\">\r\n        <!-- wp:column {\"width\":\"40%\"} -->\r\n        <div class=\"wp-block-column\" style=\"flex-basis:40%\">\r\n            <!-- wp:heading -->\r\n            <h2>Get in Touch</h2>\r\n            <!-- /wp:heading -->\r\n\r\n            <!-- wp:paragraph -->\r\n            <p>As a dedicated global relocation company, we\'re here to make your move as smooth as possible. Whether you have a question about our services, need a custom quote, or just want to say hello, we\'d love to hear from you.</p>\r\n            <!-- /wp:paragraph -->\r\n\r\n            <!-- wp:heading {\"level\":4} -->\r\n            <h4>Contact Details</h4>\r\n            <!-- /wp:heading -->\r\n\r\n            <!-- wp:list {\"className\":\"is-style-no-disc\",\"style\":{\"spacing\":{\"padding\":{\"left\":\"0\"}}}} -->\r\n            <ul class=\"is-style-no-disc\" style=\"padding-left:0\">\r\n                <!-- wp:list-item -->\r\n                <li><strong>Phone:</strong> <a href=\"tel:+15551234567\">+1 (555) 123-4567</a></li>\r\n                <!-- /wp:list-item -->\r\n                \r\n                <!-- wp:list-item -->\r\n                <li><strong>Email:</strong> <a href=\"mailto:contact@smoothmigration.com\">contact@smoothmigration.com</a></li>\r\n                <!-- /wp:list-item -->\r\n                \r\n                <!-- wp:list-item -->\r\n                <li><strong>Address:</strong> 123 Migration Lane, Suite 100, Global City, 12345</li>\r\n                <!-- /wp:list-item -->\r\n            </ul>\r\n            <!-- /wp:list -->\r\n        </div>\r\n        <!-- /wp:column -->\r\n\r\n        <!-- wp:column {\"width\":\"60%\"} -->\r\n        <div class=\"wp-block-column\" style=\"flex-basis:60%\">\r\n            <!-- wp:heading {\"level\":3} -->\r\n            <h3>Send Us a Message</h3>\r\n            <!-- /wp:heading -->\r\n            \r\n            <!-- wp:shortcode -->\r\n            [forminator_form id=\"151\"]\r\n            <!-- /wp:shortcode -->\r\n        </div>\r\n        <!-- /wp:column -->\r\n    </div>\r\n    <!-- /wp:columns -->\r\n</div>\r\n<!-- /wp:group -->','Contact','','inherit','closed','closed','','75-revision-v1','','','2025-07-19 22:19:10','2025-07-19 22:19:10','',75,'https://wp-smooth-demo.local/?p=384',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (386,1,'2025-07-19 23:43:21','2025-07-19 23:43:21','<!-- wp:html -->\n<!-- Hero Section -->\n<section class=\"hero text-center text-white d-flex align-items-center justify-content-center\">\n  <div class=\"hero-content w-100\">\n    <div class=\"container fade-in-up\">\n      <h1 class=\"display-4 fw-bold\">Your Seamless Global Relocation Starts Here</h1>\n      <p class=\"lead\">From the UK, USA, South Africa, or Canada, Smooth Migration is your trusted partner for a stress-free move. We handle the details, so you can focus on your new beginning.</p>\n      <div class=\"d-flex gap-3 justify-content-center flex-wrap mt-4\">\n        <a href=\"/contact\" class=\"btn btn-primary btn-lg\">Start Your Journey</a>\n        <a href=\"/services\" class=\"btn btn-outline-light btn-lg\">Explore Our Services</a>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- \"Who We Are\" Section -->\n<section class=\"py-5\">\n  <div class=\"container\">\n    <div class=\"row align-items-center\">\n      <div class=\"col-lg-6\">\n        <h2 class=\"display-5 fw-bold\">Who We Are at Smooth Migration</h2>\n        <p class=\"lead text-muted\">We are a team of relocation experts dedicated to making your international move as smooth and seamless as possible. With round-the-clock assistance and deep technical expertise, we navigate the complexities of relocation so you don\'t have to.</p>\n        <p>Our global network of top-tier partners ensures that you receive the best service in every aspect of your move, from finding a home to settling into your new community. We\'re with you every step of the way.</p>\n      </div>\n      <div class=\"col-lg-6 text-center\">\n        <img src=\"https://wp-smooth-demo.local/wp-content/themes/smoothmigration/assets/images/smooth-migration-logo.png\" alt=\"Smooth Migration\" class=\"img-fluid rounded-3\" style=\"max-height: 250px;\">\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- \"How It Works\" Section -->\n<section class=\"py-5 bg-light\">\n    <div class=\"container\">\n        <div class=\"text-center mb-5\">\n            <h2 class=\"display-5 fw-bold\">Your Relocation Journey, Simplified</h2>\n            <p class=\"lead text-muted\">We follow a proven process to ensure a smooth transition for you and your family.</p>\n        </div>\n        <div class=\"row text-center\">\n            <div class=\"col-md-4\">\n                <div class=\"p-4\">\n                    <div class=\"service-icon mx-auto mb-3\">\n                        <i class=\"fas fa-comments\"></i>\n                    </div>\n                    <h4>1. Consultation</h4>\n                    <p class=\"text-muted\">We start with a detailed consultation to understand your unique needs and create a customized relocation plan.</p>\n                </div>\n            </div>\n            <div class=\"col-md-4\">\n                <div class=\"p-4\">\n                    <div class=\"service-icon mx-auto mb-3\">\n                        <i class=\"fas fa-cogs\"></i>\n                    </div>\n                    <h4>2. Planning & Coordination</h4>\n                    <p class=\"text-muted\">We handle all the logistics, from visa applications to finding the perfect home, coordinating with our global partners.</p>\n                </div>\n            </div>\n            <div class=\"col-md-4\">\n                <div class=\"p-4\">\n                    <div class=\"service-icon mx-auto mb-3\">\n                        <i class=\"fas fa-handshake\"></i>\n                    </div>\n                    <h4>3. Arrival & Settling In</h4>\n                    <p class=\"text-muted\">We provide on-the-ground support to help you settle into your new life, from opening a bank account to finding the best schools.</p>\n                </div>\n            </div>\n        </div>\n    </div>\n</section>\n\n<!-- Services Section -->\n<section class=\"py-5\">\n  <div class=\"container\">\n    <div class=\"text-center mb-5\">\n      <h2 class=\"display-5 fw-bold\">Everything You Need for a Smooth Move</h2>\n      <p class=\"lead text-muted\">Our comprehensive services are designed to cover every aspect of your relocation.</p>\n    </div>\n    <div class=\"row g-4\">\n      <div class=\"col-lg-4 col-md-6\">\n        <div class=\"service-card\">\n          <div class=\"service-icon mx-auto\">\n            <i class=\"fas fa-home\"></i>\n          </div>\n          <h4>Realtor Locator</h4>\n          <p class=\"text-muted\">Find the perfect home with our network of trusted real estate agents in your new city.</p>      \n          <a href=\"/services/realtor-locator\" class=\"btn btn-outline-primary\">View Programs</a>\n        </div>\n      </div>\n      <div class=\"col-lg-4 col-md-6\">\n        <div class=\"service-card\">\n          <div class=\"service-icon mx-auto\">\n            <i class=\"fas fa-university\"></i>\n          </div>\n          <h4>Banking Services</h4>\n          <p class=\"text-muted\">Set up your finances with ease, from opening a bank account to securing a mortgage.</p>        \n          <a href=\"/services/banking-services\" class=\"btn btn-outline-primary\">View Programs</a>\n        </div>\n      </div>\n      <div class=\"col-lg-4 col-md-6\">\n        <div class=\"service-card\">\n          <div class=\"service-icon mx-auto\">\n            <i class=\"fas fa-shield-alt\"></i>\n          </div>\n          <h4>Insurance</h4>\n          <p class=\"text-muted\">Protect yourself and your family with comprehensive health, travel, and property insurance.</p>\n          <a href=\"/services/insurance\" class=\"btn btn-outline-primary\">View Programs</a>\n        </div>\n      </div>\n      <div class=\"col-lg-4 col-md-6\">\n        <div class=\"service-card\">\n          <div class=\"service-icon mx-auto\">\n            <i class=\"fas fa-exchange-alt\"></i>\n          </div>\n          <h4>International Transfers</h4>\n          <p class=\"text-muted\">Transfer money securely and efficiently with competitive exchange rates.</p>\n          <a href=\"/services/international-transfers\" class=\"btn btn-outline-primary\">View Programs</a>\n        </div>\n      </div>\n      <div class=\"col-lg-4 col-md-6\">\n        <div class=\"service-card\">\n          <div class=\"service-icon mx-auto\">\n            <i class=\"fas fa-mobile-alt\"></i>\n          </div>\n          <h4>Mobile & Cellular Plans</h4>\n          <p class=\"text-muted\">Stay connected with a local phone number and data plan from the moment you arrive.</p>      \n          <a href=\"/services/mobile-and-cellular-plans\" class=\"btn btn-outline-primary\">View Programs</a>\n        </div>\n      </div>\n      <div class=\"col-lg-4 col-md-6\">\n        <div class=\"service-card\">\n          <div class=\"service-icon mx-auto\">\n            <i class=\"fas fa-car\"></i>\n          </div>\n          <h4>Vehicles</h4>\n          <p class=\"text-muted\">Arrange for a car rental, lease, or purchase to get you on the road in your new country.</p>\n          <a href=\"/services/vehicles\" class=\"btn btn-outline-primary\">View Programs</a>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- Testimonials Section -->\n<section class=\"py-5 bg-light\">\n  <div class=\"container\">\n    <div class=\"text-center mb-5\">\n      <h2 class=\"display-5 fw-bold\">Success Stories from Our Clients</h2>\n      <p class=\"lead text-muted\">See what our clients have to say about their experience with Smooth Migration.</p>\n    </div>\n    <div class=\"row\">\n      <div class=\"col-lg-6\">\n        <div class=\"testimonial-card\">\n          <p class=\"testimonial-text\">\"The team at Smooth Migration made our move from the UK to Canada an absolute breeze. Their attention to detail and personalized service were exceptional. We couldn\'t have done it without them.\"</p>\n          <div class=\"testimonial-author\">\n            <strong>The Williams Family</strong><br>\n            <small class=\"text-muted\">Relocated from London to Toronto</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"col-lg-6\">\n        <div class=\"testimonial-card\">\n          <p class=\"testimonial-text\">\"As a professional relocating from the USA to South Africa, I was impressed with the technical expertise and round-the-clock support I received from Smooth Migration. They are true professionals.\"</p>\n          <div class=\"testimonial-author\">\n            <strong>David Chen</strong><br>\n            <small class=\"text-muted\">Relocated from New York to Cape Town</small>\n          </div>\n        </div>\n      </div>\n    </div>\n    <div class=\"text-center mt-4\">\n      <a href=\"/testimonials\" class=\"btn btn-primary\">Read More Success Stories</a>\n    </div>\n  </div>\n</section>\n\n<!-- Call to Action Section -->\n<section class=\"py-5 text-center text-white\" style=\"background: var(--primary-dark);\">\n    <div class=\"container\">\n        <h2 class=\"display-5 fw-bold\">Ready to Start Your Relocation Journey?</h2>\n        <p class=\"lead\">Let\'s make your move a smooth one. Contact us today for a free consultation.</p>\n        <a href=\"/contact\" class=\"btn btn-accent btn-lg\" style=\"background: var(--accent-color); color: var(--text-dark);\">Get Your Free Consultation</a>\n    </div>\n</section>\n<!-- /wp:html -->','Home','','inherit','closed','closed','','296-revision-v1','','','2025-07-19 23:43:21','2025-07-19 23:43:21','',296,'https://wp-smooth-demo.local/?p=386',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (387,2,'2025-07-21 01:14:03','2025-07-21 01:14:03','','realtor-form','','publish','closed','closed','','realtor-form','','','2025-07-24 00:41:03','2025-07-24 00:41:03','',0,'https://stormy-support.localsite.io/?post_type=forminator_forms&#038;p=387',0,'forminator_forms','',0);
INSERT INTO `wp_posts` VALUES (394,2,'2025-07-21 01:53:11','2025-07-21 01:53:11','<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"8rem\",\"bottom\":\"var:preset|spacing|70\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"color\":{\"gradient\":\"linear-gradient(135deg,#175873 0%,#2c6c8a 100%)\"}},\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-color has-text-color has-background\" style=\"background:linear-gradient(135deg,#175873 0%,#2c6c8a 100%);margin-top:0;margin-bottom:0;padding-top:8rem;padding-bottom:var(--wp--preset--spacing--70)\">\n    <!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"clamp(2.5rem, 5vw, 4rem)\",\"fontWeight\":\"800\",\"lineHeight\":\"1.1\",\"textShadow\":\"2px 2px 4px rgba(0,0,0,0.3)\"},\"spacing\":{\"margin\":{\"bottom\":\"1.5rem\"}}}} -->\n    <h1 class=\"wp-block-heading has-text-align-center\" style=\"margin-bottom:1.5rem;font-size:clamp(2.5rem, 5vw, 4rem);font-weight:800;line-height:1.1;text-shadow:2px 2px 4px rgba(0,0,0,0.3)\">Find Your Perfect Home</h1>\n    <!-- /wp:heading -->\n\n    <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"400\",\"lineHeight\":\"1.6\",\"opacity\":\"0.9\"},\"spacing\":{\"margin\":{\"bottom\":\"2rem\"},\"padding\":{\"left\":\"1rem\",\"right\":\"1rem\"}}}} -->\n    <p class=\"has-text-align-center\" style=\"margin-bottom:2rem;padding-left:1rem;padding-right:1rem;font-size:1.25rem;font-weight:400;line-height:1.6;opacity:0.9\">Connect with our expert realtors who specialize in helping international clients find their ideal home. We\'re excited to work with you and make your relocation smooth and stress-free.</p>\n    <!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"4rem\",\"bottom\":\"4rem\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:4rem;padding-bottom:4rem\">\n    <!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|60\"}}}} -->\n    <div class=\"wp-block-columns alignwide\">\n        <!-- wp:column {\"width\":\"50%\"} -->\n        <div class=\"wp-block-column\" style=\"flex-basis:50%\">\n            <!-- wp:heading {\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"2.5rem\",\"fontWeight\":\"700\",\"lineHeight\":\"1.2\",\"color\":\"#222428\"},\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n            <h2 class=\"wp-block-heading\" style=\"color:#222428;margin-bottom:1rem;font-size:2.5rem;font-weight:700;line-height:1.2\">Why Choose Our Realtors?</h2>\n            <!-- /wp:heading -->\n\n            <!-- wp:list {\"style\":{\"spacing\":{\"padding\":{\"left\":\"0\"}},\"typography\":{\"fontSize\":\"1.1rem\",\"lineHeight\":\"1.8\",\"color\":\"#222428\"}}} -->\n            <ul style=\"color:#222428;padding-left:0;font-size:1.1rem;line-height:1.8\">\n                <!-- wp:list-item -->\n                <li><strong style=\"color:#175873\">Local Market Expertise:</strong> Our realtors have deep knowledge of your destination city\'s neighborhoods, schools, and amenities.</li>\n                <!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong style=\"color:#175873\">International Experience:</strong> We specialize in helping expats and international clients navigate the local real estate market.</li>\n                <!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong style=\"color:#175873\">Virtual Tours Available:</strong> Can\'t visit in person? We offer comprehensive virtual property tours and video calls.</li>\n                <!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong style=\"color:#175873\">Full-Service Support:</strong> From property search to closing, we handle every step of your home buying or renting process.</li>\n                <!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong style=\"color:#175873\">Multilingual Service:</strong> Our team speaks multiple languages to ensure clear communication throughout your journey.</li>\n                <!-- /wp:list-item -->\n            </ul>\n            <!-- /wp:list -->\n\n            <!-- wp:separator {\"style\":{\"spacing\":{\"margin\":{\"top\":\"3rem\",\"bottom\":\"3rem\"}},\"color\":{\"background\":\"#e0e0e0\"}}} -->\n            <hr class=\"wp-block-separator has-alpha-channel-opacity\" style=\"margin-top:3rem;margin-bottom:3rem;background-color:#e0e0e0\"/>\n            <!-- /wp:separator -->\n\n            <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\",\"fontWeight\":\"700\",\"color\":\"#222428\"},\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n            <h3 class=\"wp-block-heading\" style=\"color:#222428;margin-bottom:1rem;font-size:1.5rem;font-weight:700\">What Happens Next?</h3>\n            <!-- /wp:heading -->\n\n            <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.1rem\",\"lineHeight\":\"1.7\",\"color\":\"#6b7280\"}}} -->\n            <p style=\"color:#6b7280;font-size:1.1rem;line-height:1.7\">Once you submit the form, one of our expert realtors will contact you within 24 hours to discuss your needs, budget, and preferred locations. We\'ll then provide you with a curated list of properties that match your criteria and schedule virtual or in-person viewings at your convenience.</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column {\"width\":\"50%\"} -->\n        <div class=\"wp-block-column\" style=\"flex-basis:50%\">\n            <!-- wp:group {\"style\":{\"border\":{\"radius\":\"0.5rem\",\"width\":\"1px\"},\"spacing\":{\"padding\":{\"top\":\"3rem\",\"bottom\":\"3rem\",\"left\":\"3rem\",\"right\":\"3rem\"}},\"color\":{\"background\":\"#f4f5f8\"}},\"borderColor\":\"base-3\",\"layout\":{\"type\":\"constrained\"}} -->\n            <div class=\"wp-block-group has-border-color has-base-3-border-color has-background\" style=\"border-width:1px;border-radius:0.5rem;background-color:#f4f5f8;padding-top:3rem;padding-right:3rem;padding-bottom:3rem;padding-left:3rem\">\n                <!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.75rem\",\"fontWeight\":\"700\",\"color\":\"#222428\"},\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n                <h3 class=\"wp-block-heading has-text-align-center\" style=\"color:#222428;margin-bottom:1rem;font-size:1.75rem;font-weight:700\">Get Started Today</h3>\n                <!-- /wp:heading -->\n\n                <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1rem\",\"color\":\"#6b7280\"},\"spacing\":{\"margin\":{\"bottom\":\"2rem\"}}}} -->\n                <p class=\"has-text-align-center\" style=\"color:#6b7280;margin-bottom:2rem;font-size:1rem\">Fill out the form below and let us help you find your dream home in your new city.</p>\n                <!-- /wp:paragraph -->\n\n                <!-- wp:html -->\n                [forminator_form id=\"387\"]\n                <!-- /wp:html -->\n            </div>\n            <!-- /wp:group -->\n        </div>\n        <!-- /wp:column -->\n    </div>\n    <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"color\":{\"background\":\"#175873\"},\"spacing\":{\"padding\":{\"top\":\"3rem\",\"bottom\":\"3rem\"}}},\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-color has-text-color has-background\" style=\"background-color:#175873;padding-top:3rem;padding-bottom:3rem\">\n    <!-- wp:columns {\"align\":\"wide\"} -->\n    <div class=\"wp-block-columns alignwide\">\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">🏠 Property Search</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\",\"opacity\":\"0.9\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem;opacity:0.9\">Curated listings based on your preferences</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">📹 Virtual Tours</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\",\"opacity\":\"0.9\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem;opacity:0.9\">See properties from anywhere in the world</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">🤝 Full Support</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\",\"opacity\":\"0.9\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem;opacity:0.9\">From search to closing, we\'re with you</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n    </div>\n    <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->','Realtor Locator','','publish','closed','closed','','realtor-form','','','2025-07-26 04:47:43','2025-07-26 04:47:43','',296,'https://stormy-support.localsite.io/?page_id=394',0,'page','',0);
