INSERT INTO `wp_posts` VALUES (5052,2,'2025-07-21 23:47:32','2025-07-21 23:47:32','<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"8rem\",\"bottom\":\"var:preset|spacing|70\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"color\":{\"gradient\":\"linear-gradient(135deg,#175873 0%,#2c6c8a 100%)\"}},\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-color has-text-color has-background\" style=\"background:linear-gradient(135deg,#175873 0%,#2c6c8a 100%);margin-top:0;margin-bottom:0;padding-top:8rem;padding-bottom:var(--wp--preset--spacing--70)\">\n    <!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"clamp(2.5rem, 5vw, 4rem)\",\"fontWeight\":\"800\",\"lineHeight\":\"1.1\",\"textShadow\":\"2px 2px 4px rgba(0,0,0,0.3)\"},\"spacing\":{\"margin\":{\"bottom\":\"1.5rem\"}}}} -->\n    <h1 class=\"wp-block-heading has-text-align-center\" style=\"margin-bottom:1.5rem;font-size:clamp(2.5rem, 5vw, 4rem);font-weight:800;line-height:1.1;text-shadow:2px 2px 4px rgba(0,0,0,0.3)\">Become a Partner</h1>\n    <!-- /wp:heading -->\n\n    <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"400\",\"lineHeight\":\"1.6\",\"opacity\":\"0.9\"},\"spacing\":{\"margin\":{\"bottom\":\"2rem\"},\"padding\":{\"left\":\"1rem\",\"right\":\"1rem\"}}}} -->\n    <p class=\"has-text-align-center\" style=\"margin-bottom:2rem;padding-left:1rem;padding-right:1rem;font-size:1.25rem;font-weight:400;line-height:1.6;opacity:0.9\">Join our global network of trusted service providers and help make international relocations smooth and successful. Together, we can serve clients worldwide.</p>\n    <!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"4rem\",\"bottom\":\"4rem\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:4rem;padding-bottom:4rem\">\n    <!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|60\"}}}} -->\n    <div class=\"wp-block-columns alignwide\">\n        <!-- wp:column {\"width\":\"50%\"} -->\n        <div class=\"wp-block-column\" style=\"flex-basis:50%\">\n            <!-- wp:heading {\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"2.5rem\",\"fontWeight\":\"700\",\"lineHeight\":\"1.2\",\"color\":\"#222428\"},\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n            <h2 class=\"wp-block-heading\" style=\"color:#222428;margin-bottom:1rem;font-size:2.5rem;font-weight:700;line-height:1.2\">Why Partner With Us?</h2>\n            <!-- /wp:heading -->\n\n            <!-- wp:list {\"style\":{\"spacing\":{\"padding\":{\"left\":\"0\"}},\"typography\":{\"fontSize\":\"1.1rem\",\"lineHeight\":\"1.8\",\"color\":\"#222428\"}}} -->\n            <ul style=\"color:#222428;padding-left:0;font-size:1.1rem;line-height:1.8\">\n                <!-- wp:list-item -->\n                <li><strong style=\"color:#175873\">Global Reach:</strong> Access to clients from 50+ countries seeking relocation services in your area of expertise.</li>\n                <!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong style=\"color:#175873\">Steady Revenue Stream:</strong> Consistent referrals and partnership opportunities to grow your business.</li>\n                <!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong style=\"color:#175873\">Marketing Support:</strong> We promote our partners through our website, social media, and client communications.</li>\n                <!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong style=\"color:#175873\">Quality Clients:</strong> Pre-qualified leads who are serious about their relocation and ready to invest in quality services.</li>\n                <!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong style=\"color:#175873\">Partnership Benefits:</strong> Exclusive partner rates, priority support, and co-marketing opportunities.</li>\n                <!-- /wp:list-item -->\n            </ul>\n            <!-- /wp:list -->\n\n            <!-- wp:separator {\"style\":{\"spacing\":{\"margin\":{\"top\":\"3rem\",\"bottom\":\"3rem\"}},\"color\":{\"background\":\"#e0e0e0\"}}} -->\n            <hr class=\"wp-block-separator has-alpha-channel-opacity\" style=\"margin-top:3rem;margin-bottom:3rem;background-color:#e0e0e0\"/>\n            <!-- /wp:separator -->\n\n            <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.75rem\",\"fontWeight\":\"700\",\"color\":\"#222428\"},\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n            <h3 class=\"wp-block-heading\" style=\"color:#222428;margin-bottom:1rem;font-size:1.75rem;font-weight:700\">Services We\'re Looking For</h3>\n            <!-- /wp:heading -->\n\n            <!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"var:preset|spacing|40\"}}}} -->\n            <div class=\"wp-block-columns\">\n                <!-- wp:column -->\n                <div class=\"wp-block-column\">\n                    <!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"1rem\",\"color\":\"#6b7280\"}}} -->\n                    <ul style=\"color:#6b7280;font-size:1rem\">\n                        <!-- wp:list-item -->\n                        <li>Real Estate Services</li>\n                        <!-- /wp:list-item -->\n                        <!-- wp:list-item -->\n                        <li>Banking & Financial</li>\n                        <!-- /wp:list-item -->\n                        <!-- wp:list-item -->\n                        <li>Immigration Law</li>\n                        <!-- /wp:list-item -->\n                        <!-- wp:list-item -->\n                        <li>Insurance Services</li>\n                        <!-- /wp:list-item -->\n                    </ul>\n                    <!-- /wp:list -->\n                </div>\n                <!-- /wp:column -->\n\n                <!-- wp:column -->\n                <div class=\"wp-block-column\">\n                    <!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"1rem\",\"color\":\"#6b7280\"}}} -->\n                    <ul style=\"color:#6b7280;font-size:1rem\">\n                        <!-- wp:list-item -->\n                        <li>Moving & Logistics</li>\n                        <!-- /wp:list-item -->\n                        <!-- wp:list-item -->\n                        <li>Tax & Accounting</li>\n                        <!-- /wp:list-item -->\n                        <!-- wp:list-item -->\n                        <li>Educational Services</li>\n                        <!-- /wp:list-item -->\n                        <!-- wp:list-item -->\n                        <li>Pet Relocation</li>\n                        <!-- /wp:list-item -->\n                    </ul>\n                    <!-- /wp:list -->\n                </div>\n                <!-- /wp:column -->\n            </div>\n            <!-- /wp:columns -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column {\"width\":\"50%\"} -->\n        <div class=\"wp-block-column\" style=\"flex-basis:50%\">\n            <!-- wp:group {\"style\":{\"border\":{\"radius\":\"0.5rem\",\"width\":\"1px\"},\"spacing\":{\"padding\":{\"top\":\"3rem\",\"bottom\":\"3rem\",\"left\":\"3rem\",\"right\":\"3rem\"}},\"color\":{\"background\":\"#f4f5f8\"}},\"borderColor\":\"base-3\",\"layout\":{\"type\":\"constrained\"}} -->\n            <div class=\"wp-block-group has-border-color has-base-3-border-color has-background\" style=\"border-width:1px;border-radius:0.5rem;background-color:#f4f5f8;padding-top:3rem;padding-right:3rem;padding-bottom:3rem;padding-left:3rem\">\n                <!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.75rem\",\"fontWeight\":\"700\",\"color\":\"#222428\"},\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n                <h3 class=\"wp-block-heading has-text-align-center\" style=\"color:#222428;margin-bottom:1rem;font-size:1.75rem;font-weight:700\">Apply to Partner</h3>\n                <!-- /wp:heading -->\n\n                <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1rem\",\"color\":\"#6b7280\"},\"spacing\":{\"margin\":{\"bottom\":\"2rem\"}}}} -->\n                <p class=\"has-text-align-center\" style=\"color:#6b7280;margin-bottom:2rem;font-size:1rem\">Ready to join our network? Fill out the partnership application below and we\'ll be in touch within 48 hours.</p>\n                <!-- /wp:paragraph -->\n\n                <!-- wp:html -->\n                [forminator_form id=\"5051\"]\n                <!-- /wp:html -->\n            </div>\n            <!-- /wp:group -->\n        </div>\n        <!-- /wp:column -->\n    </div>\n    <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"color\":{\"background\":\"#175873\"},\"spacing\":{\"padding\":{\"top\":\"3rem\",\"bottom\":\"3rem\"}}},\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-color has-text-color has-background\" style=\"background-color:#175873;padding-top:3rem;padding-bottom:3rem\">\n    <!-- wp:heading {\"textAlign\":\"center\",\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"2rem\",\"fontWeight\":\"700\"},\"spacing\":{\"margin\":{\"bottom\":\"2rem\"}}}} -->\n    <h2 class=\"wp-block-heading has-text-align-center\" style=\"margin-bottom:2rem;font-size:2rem;font-weight:700\">Partnership Process</h2>\n    <!-- /wp:heading -->\n\n    <!-- wp:columns {\"align\":\"wide\"} -->\n    <div class=\"wp-block-columns alignwide\">\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">1️⃣ Application</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\",\"opacity\":\"0.9\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem;opacity:0.9\">Submit your partnership application with business details</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">2️⃣ Review</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\",\"opacity\":\"0.9\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem;opacity:0.9\">We review your credentials and service offerings</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">3️⃣ Onboarding</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\",\"opacity\":\"0.9\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem;opacity:0.9\">Welcome to the network! Start receiving referrals</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n    </div>\n    <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->','Become a Partner','','publish','closed','closed','','become-a-partner','','','2025-07-24 00:15:05','2025-07-24 00:15:05','',0,'https://stormy-support.localsite.io/?page_id=5052',0,'page','',0);
