INSERT INTO `wp_posts` VALUES (5057,1,'2025-07-24 00:07:50','2025-07-24 00:07:50','<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|70\",\"bottom\":\"var:preset|spacing|70\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"color\":{\"gradient\":\"linear-gradient(135deg,rgb(16,185,129) 0%,rgb(5,150,105) 100%)\"}},\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-color has-text-color has-background\" style=\"background:linear-gradient(135deg,rgb(16,185,129) 0%,rgb(5,150,105) 100%);margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--70);padding-bottom:var(--wp--preset--spacing--70)\">\n    <!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"3.5rem\",\"fontWeight\":\"700\",\"lineHeight\":\"1.2\"},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|50\"}}}} -->\n    <h1 class=\"wp-block-heading has-text-align-center\" style=\"margin-bottom:var(--wp--preset--spacing--50);font-size:3.5rem;font-weight:700;line-height:1.2\">Get In Touch</h1>\n    <!-- /wp:heading -->\n\n    <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"lineHeight\":\"1.6\"},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|60\"}}}} -->\n    <p class=\"has-text-align-center\" style=\"margin-bottom:var(--wp--preset--spacing--60);font-size:1.25rem;line-height:1.6\">Ready to start your smooth migration journey? We\'re here to help you every step of the way. Reach out to us and let\'s make your international move seamless.</p>\n    <!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|70\",\"bottom\":\"var:preset|spacing|70\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--70);padding-bottom:var(--wp--preset--spacing--70)\">\n    <!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|60\"}}}} -->\n    <div class=\"wp-block-columns alignwide\">\n        <!-- wp:column {\"width\":\"40%\"} -->\n        <div class=\"wp-block-column\" style=\"flex-basis:40%\">\n            <!-- wp:heading {\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"2.5rem\",\"fontWeight\":\"600\"},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|50\"}}}} -->\n            <h2 class=\"wp-block-heading\" style=\"margin-bottom:var(--wp--preset--spacing--50);font-size:2.5rem;font-weight:600\">Let\'s Talk</h2>\n            <!-- /wp:heading -->\n\n            <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.1rem\",\"lineHeight\":\"1.7\"},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|50\"}}}} -->\n            <p style=\"margin-bottom:var(--wp--preset--spacing--50);font-size:1.1rem;line-height:1.7\">Whether you have questions about our services, need help planning your move, or want to discuss a custom solution, we\'re here to help. Our team of relocation experts is ready to provide personalized assistance for your unique situation.</p>\n            <!-- /wp:paragraph -->\n\n            <!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n            <div class=\"wp-block-group\" style=\"margin-bottom:var(--wp--preset--spacing--50)\">\n                <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\",\"fontWeight\":\"500\"},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|30\"}}}} -->\n                <h3 class=\"wp-block-heading\" style=\"margin-bottom:var(--wp--preset--spacing--30);font-size:1.5rem;font-weight:500\">📞 Phone Support</h3>\n                <!-- /wp:heading -->\n                <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.1rem\"}}} -->\n                <p style=\"font-size:1.1rem\"><strong>+1 (555) 123-4567</strong><br>Monday - Friday: 9:00 AM - 6:00 PM EST<br>Saturday: 10:00 AM - 4:00 PM EST</p>\n                <!-- /wp:paragraph -->\n            </div>\n            <!-- /wp:group -->\n\n            <!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n            <div class=\"wp-block-group\" style=\"margin-bottom:var(--wp--preset--spacing--50)\">\n                <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\",\"fontWeight\":\"500\"},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|30\"}}}} -->\n                <h3 class=\"wp-block-heading\" style=\"margin-bottom:var(--wp--preset--spacing--30);font-size:1.5rem;font-weight:500\">✉️ Email Support</h3>\n                <!-- /wp:heading -->\n                <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.1rem\"}}} -->\n                <p style=\"font-size:1.1rem\"><strong>hello@smoothmigration.com</strong><br>We typically respond within 2-4 hours during business days</p>\n                <!-- /wp:paragraph -->\n            </div>\n            <!-- /wp:group -->\n\n            <!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n            <div class=\"wp-block-group\">\n                <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\",\"fontWeight\":\"500\"},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|30\"}}}} -->\n                <h3 class=\"wp-block-heading\" style=\"margin-bottom:var(--wp--preset--spacing--30);font-size:1.5rem;font-weight:500\">🕐 Response Time</h3>\n                <!-- /wp:heading -->\n                <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.1rem\"}}} -->\n                <p style=\"font-size:1.1rem\">We pride ourselves on quick response times. Most inquiries are answered within 24 hours, and urgent matters are handled immediately.</p>\n                <!-- /wp:paragraph -->\n            </div>\n            <!-- /wp:group -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column {\"width\":\"60%\"} -->\n        <div class=\"wp-block-column\" style=\"flex-basis:60%\">\n            <!-- wp:group {\"style\":{\"border\":{\"radius\":\"12px\",\"width\":\"1px\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|60\",\"right\":\"var:preset|spacing|60\"}},\"color\":{\"background\":\"#f8f9fa\"}},\"borderColor\":\"base-3\",\"layout\":{\"type\":\"constrained\"}} -->\n            <div class=\"wp-block-group has-border-color has-base-3-border-color has-background\" style=\"border-width:1px;border-radius:12px;background-color:#f8f9fa;padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--60)\">\n                <!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.75rem\",\"fontWeight\":\"600\"},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|40\"}}}} -->\n                <h3 class=\"wp-block-heading has-text-align-center\" style=\"margin-bottom:var(--wp--preset--spacing--40);font-size:1.75rem;font-weight:600\">Send Us a Message</h3>\n                <!-- /wp:heading -->\n\n                <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1rem\"},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|50\"}}}} -->\n                <p class=\"has-text-align-center\" style=\"margin-bottom:var(--wp--preset--spacing--50);font-size:1rem\">Fill out the form below and we\'ll get back to you as soon as possible.</p>\n                <!-- /wp:paragraph -->\n\n                <!-- wp:html -->\n                [forminator_form id=\"151\"]\n                <!-- /wp:html -->\n            </div>\n            <!-- /wp:group -->\n        </div>\n        <!-- /wp:column -->\n    </div>\n    <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"color\":{\"background\":\"#065f46\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-color has-text-color has-background\" style=\"background-color:#065f46;padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n    <!-- wp:heading {\"textAlign\":\"center\",\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"2rem\",\"fontWeight\":\"600\"},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|50\"}}}} -->\n    <h2 class=\"wp-block-heading has-text-align-center\" style=\"margin-bottom:var(--wp--preset--spacing--50);font-size:2rem;font-weight:600\">Ready to Get Started?</h2>\n    <!-- /wp:heading -->\n\n    <!-- wp:columns {\"align\":\"wide\"} -->\n    <div class=\"wp-block-columns alignwide\">\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">🌍 Global Services</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem\">We serve clients moving to 50+ countries worldwide</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">⚡ Fast Response</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem\">Quick replies and immediate assistance when you need it</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">🎯 Personalized</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem\">Tailored solutions for your unique relocation needs</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n    </div>\n    <!-- /wp:columns -->\n</div>\n<!-- /wp:group --> ','Contact','','inherit','closed','closed','','75-revision-v1','','','2025-07-24 00:07:50','2025-07-24 00:07:50','',75,'https://wp-smooth-demo.local/?p=5057',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (5058,1,'2025-07-24 00:08:03','2025-07-24 00:08:03','<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|70\",\"bottom\":\"var:preset|spacing|70\"}}},\"layout\":{\"type\":\"constrained\"}} -->\r\n<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--70);padding-bottom:var(--wp--preset--spacing--70)\">\r\n    <!-- wp:columns {\"verticalAlignment\":\"top\",\"align\":\"wide\"} -->\r\n    <div class=\"wp-block-columns alignwide are-vertically-aligned-top\">\r\n        <!-- wp:column {\"width\":\"40%\"} -->\r\n        <div class=\"wp-block-column\" style=\"flex-basis:40%\">\r\n            <!-- wp:heading -->\r\n            <h2>Get in Touch</h2>\r\n            <!-- /wp:heading -->\r\n\r\n            <!-- wp:paragraph -->\r\n            <p>As a dedicated global relocation company, we\'re here to make your move as smooth as possible. Whether you have a question about our services, need a custom quote, or just want to say hello, we\'d love to hear from you.</p>\r\n            <!-- /wp:paragraph -->\r\n\r\n            <!-- wp:heading {\"level\":4} -->\r\n            <h4>Contact Details</h4>\r\n            <!-- /wp:heading -->\r\n\r\n            <!-- wp:list {\"className\":\"is-style-no-disc\",\"style\":{\"spacing\":{\"padding\":{\"left\":\"0\"}}}} -->\r\n            <ul class=\"is-style-no-disc\" style=\"padding-left:0\">\r\n                <!-- wp:list-item -->\r\n                <li><strong>Phone:</strong> <a href=\"tel:+15551234567\">+1 (555) 123-4567</a></li>\r\n                <!-- /wp:list-item -->\r\n                \r\n                <!-- wp:list-item -->\r\n                <li><strong>Email:</strong> <a href=\"mailto:contact@smoothmigration.com\">contact@smoothmigration.com</a></li>\r\n                <!-- /wp:list-item -->\r\n                \r\n                <!-- wp:list-item -->\r\n                <li><strong>Address:</strong> 123 Migration Lane, Suite 100, Global City, 12345</li>\r\n                <!-- /wp:list-item -->\r\n            </ul>\r\n            <!-- /wp:list -->\r\n        </div>\r\n        <!-- /wp:column -->\r\n\r\n        <!-- wp:column {\"width\":\"60%\"} -->\r\n        <div class=\"wp-block-column\" style=\"flex-basis:60%\">\r\n            <!-- wp:heading {\"level\":3} -->\r\n            <h3>Send Us a Message</h3>\r\n            <!-- /wp:heading -->\r\n            \r\n            <!-- wp:shortcode -->\r\n            [forminator_form id=\"151\"]\r\n            <!-- /wp:shortcode -->\r\n        </div>\r\n        <!-- /wp:column -->\r\n    </div>\r\n    <!-- /wp:columns -->\r\n</div>\r\n<!-- /wp:group -->','Contact','','inherit','closed','closed','','75-revision-v1','','','2025-07-24 00:08:03','2025-07-24 00:08:03','',75,'https://wp-smooth-demo.local/?p=5058',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (5059,1,'2025-07-24 00:08:50','2025-07-24 00:08:50','<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|70\",\"bottom\":\"var:preset|spacing|70\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"color\":{\"gradient\":\"linear-gradient(135deg,rgb(74,144,226) 0%,rgb(80,101,166) 100%)\"}},\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-color has-text-color has-background\" style=\"background:linear-gradient(135deg,rgb(74,144,226) 0%,rgb(80,101,166) 100%);margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--70);padding-bottom:var(--wp--preset--spacing--70)\">\n    <!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"3.5rem\",\"fontWeight\":\"700\",\"lineHeight\":\"1.2\"},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|50\"}}}} -->\n    <h1 class=\"wp-block-heading has-text-align-center\" style=\"margin-bottom:var(--wp--preset--spacing--50);font-size:3.5rem;font-weight:700;line-height:1.2\">Find Your Perfect Home</h1>\n    <!-- /wp:heading -->\n\n    <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"lineHeight\":\"1.6\"},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|60\"}}}} -->\n    <p class=\"has-text-align-center\" style=\"margin-bottom:var(--wp--preset--spacing--60);font-size:1.25rem;line-height:1.6\">Connect with our expert realtors who specialize in helping international clients find their ideal home. We\'re excited to work with you and make your relocation smooth and stress-free.</p>\n    <!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|70\",\"bottom\":\"var:preset|spacing|70\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--70);padding-bottom:var(--wp--preset--spacing--70)\">\n    <!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|60\"}}}} -->\n    <div class=\"wp-block-columns alignwide\">\n        <!-- wp:column {\"width\":\"50%\"} -->\n        <div class=\"wp-block-column\" style=\"flex-basis:50%\">\n            <!-- wp:heading {\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"2.5rem\",\"fontWeight\":\"600\"},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|50\"}}}} -->\n            <h2 class=\"wp-block-heading\" style=\"margin-bottom:var(--wp--preset--spacing--50);font-size:2.5rem;font-weight:600\">Why Choose Our Realtors?</h2>\n            <!-- /wp:heading -->\n\n            <!-- wp:list {\"style\":{\"spacing\":{\"padding\":{\"left\":\"0\"}},\"typography\":{\"fontSize\":\"1.1rem\",\"lineHeight\":\"1.8\"}},\"className\":\"is-style-checkmark-list\"} -->\n            <ul class=\"is-style-checkmark-list\" style=\"padding-left:0;font-size:1.1rem;line-height:1.8\">\n                <!-- wp:list-item -->\n                <li><strong>Local Market Expertise:</strong> Our realtors have deep knowledge of your destination city\'s neighborhoods, schools, and amenities.</li>\n                <!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong>International Experience:</strong> We specialize in helping expats and international clients navigate the local real estate market.</li>\n                <!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong>Virtual Tours Available:</strong> Can\'t visit in person? We offer comprehensive virtual property tours and video calls.</li>\n                <!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong>Full-Service Support:</strong> From property search to closing, we handle every step of your home buying or renting process.</li>\n                <!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong>Multilingual Service:</strong> Our team speaks multiple languages to ensure clear communication throughout your journey.</li>\n                <!-- /wp:list-item -->\n            </ul>\n            <!-- /wp:list -->\n\n            <!-- wp:separator {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}}} -->\n            <hr class=\"wp-block-separator has-alpha-channel-opacity\" style=\"margin-top:var(--wp--preset--spacing--60);margin-bottom:var(--wp--preset--spacing--60)\"/>\n            <!-- /wp:separator -->\n\n            <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\",\"fontWeight\":\"500\"},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|30\"}}}} -->\n            <h3 class=\"wp-block-heading\" style=\"margin-bottom:var(--wp--preset--spacing--30);font-size:1.5rem;font-weight:500\">What Happens Next?</h3>\n            <!-- /wp:heading -->\n\n            <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.1rem\",\"lineHeight\":\"1.7\"}}} -->\n            <p style=\"font-size:1.1rem;line-height:1.7\">Once you submit the form, one of our expert realtors will contact you within 24 hours to discuss your needs, budget, and preferred locations. We\'ll then provide you with a curated list of properties that match your criteria and schedule virtual or in-person viewings at your convenience.</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column {\"width\":\"50%\"} -->\n        <div class=\"wp-block-column\" style=\"flex-basis:50%\">\n            <!-- wp:group {\"style\":{\"border\":{\"radius\":\"12px\",\"width\":\"1px\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|60\",\"right\":\"var:preset|spacing|60\"}},\"color\":{\"background\":\"#f8f9fa\"}},\"borderColor\":\"base-3\",\"layout\":{\"type\":\"constrained\"}} -->\n            <div class=\"wp-block-group has-border-color has-base-3-border-color has-background\" style=\"border-width:1px;border-radius:12px;background-color:#f8f9fa;padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--60)\">\n                <!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.75rem\",\"fontWeight\":\"600\"},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|40\"}}}} -->\n                <h3 class=\"wp-block-heading has-text-align-center\" style=\"margin-bottom:var(--wp--preset--spacing--40);font-size:1.75rem;font-weight:600\">Get Started Today</h3>\n                <!-- /wp:heading -->\n\n                <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1rem\"},\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|50\"}}}} -->\n                <p class=\"has-text-align-center\" style=\"margin-bottom:var(--wp--preset--spacing--50);font-size:1rem\">Fill out the form below and let us help you find your dream home in your new city.</p>\n                <!-- /wp:paragraph -->\n\n                <!-- wp:html -->\n                [forminator_form id=\"387\"]\n                <!-- /wp:html -->\n            </div>\n            <!-- /wp:group -->\n        </div>\n        <!-- /wp:column -->\n    </div>\n    <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"color\":{\"background\":\"#1e3a8a\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-color has-text-color has-background\" style=\"background-color:#1e3a8a;padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\">\n    <!-- wp:columns {\"align\":\"wide\"} -->\n    <div class=\"wp-block-columns alignwide\">\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">🏠 Property Search</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem\">Curated listings based on your preferences</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">📹 Virtual Tours</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem\">See properties from anywhere in the world</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">🤝 Full Support</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem\">From search to closing, we\'re with you</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n    </div>\n    <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->','Realtor Form','','inherit','closed','closed','','394-revision-v1','','','2025-07-24 00:08:50','2025-07-24 00:08:50','',394,'https://wp-smooth-demo.local/?p=5059',0,'revision','',0);
