INSERT INTO `wp_posts` VALUES (5061,1,'2025-07-24 00:14:12','2025-07-24 00:14:12','<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"8rem\",\"bottom\":\"var:preset|spacing|70\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"color\":{\"gradient\":\"linear-gradient(135deg,#175873 0%,#2c6c8a 100%)\"}},\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-color has-text-color has-background\" style=\"background:linear-gradient(135deg,#175873 0%,#2c6c8a 100%);margin-top:0;margin-bottom:0;padding-top:8rem;padding-bottom:var(--wp--preset--spacing--70)\">\n    <!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"clamp(2.5rem, 5vw, 4rem)\",\"fontWeight\":\"800\",\"lineHeight\":\"1.1\",\"textShadow\":\"2px 2px 4px rgba(0,0,0,0.3)\"},\"spacing\":{\"margin\":{\"bottom\":\"1.5rem\"}}}} -->\n    <h1 class=\"wp-block-heading has-text-align-center\" style=\"margin-bottom:1.5rem;font-size:clamp(2.5rem, 5vw, 4rem);font-weight:800;line-height:1.1;text-shadow:2px 2px 4px rgba(0,0,0,0.3)\">Find Your Perfect Home</h1>\n    <!-- /wp:heading -->\n\n    <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"400\",\"lineHeight\":\"1.6\",\"opacity\":\"0.9\"},\"spacing\":{\"margin\":{\"bottom\":\"2rem\"},\"padding\":{\"left\":\"1rem\",\"right\":\"1rem\"}}}} -->\n    <p class=\"has-text-align-center\" style=\"margin-bottom:2rem;padding-left:1rem;padding-right:1rem;font-size:1.25rem;font-weight:400;line-height:1.6;opacity:0.9\">Connect with our expert realtors who specialize in helping international clients find their ideal home. We\'re excited to work with you and make your relocation smooth and stress-free.</p>\n    <!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"4rem\",\"bottom\":\"4rem\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:4rem;padding-bottom:4rem\">\n    <!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|60\"}}}} -->\n    <div class=\"wp-block-columns alignwide\">\n        <!-- wp:column {\"width\":\"50%\"} -->\n        <div class=\"wp-block-column\" style=\"flex-basis:50%\">\n            <!-- wp:heading {\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"2.5rem\",\"fontWeight\":\"700\",\"lineHeight\":\"1.2\",\"color\":\"#222428\"},\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n            <h2 class=\"wp-block-heading\" style=\"color:#222428;margin-bottom:1rem;font-size:2.5rem;font-weight:700;line-height:1.2\">Why Choose Our Realtors?</h2>\n            <!-- /wp:heading -->\n\n            <!-- wp:list {\"style\":{\"spacing\":{\"padding\":{\"left\":\"0\"}},\"typography\":{\"fontSize\":\"1.1rem\",\"lineHeight\":\"1.8\",\"color\":\"#222428\"}}} -->\n            <ul style=\"color:#222428;padding-left:0;font-size:1.1rem;line-height:1.8\">\n                <!-- wp:list-item -->\n                <li><strong style=\"color:#175873\">Local Market Expertise:</strong> Our realtors have deep knowledge of your destination city\'s neighborhoods, schools, and amenities.</li>\n                <!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong style=\"color:#175873\">International Experience:</strong> We specialize in helping expats and international clients navigate the local real estate market.</li>\n                <!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong style=\"color:#175873\">Virtual Tours Available:</strong> Can\'t visit in person? We offer comprehensive virtual property tours and video calls.</li>\n                <!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong style=\"color:#175873\">Full-Service Support:</strong> From property search to closing, we handle every step of your home buying or renting process.</li>\n                <!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong style=\"color:#175873\">Multilingual Service:</strong> Our team speaks multiple languages to ensure clear communication throughout your journey.</li>\n                <!-- /wp:list-item -->\n            </ul>\n            <!-- /wp:list -->\n\n            <!-- wp:separator {\"style\":{\"spacing\":{\"margin\":{\"top\":\"3rem\",\"bottom\":\"3rem\"}},\"color\":{\"background\":\"#e0e0e0\"}}} -->\n            <hr class=\"wp-block-separator has-alpha-channel-opacity\" style=\"margin-top:3rem;margin-bottom:3rem;background-color:#e0e0e0\"/>\n            <!-- /wp:separator -->\n\n            <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\",\"fontWeight\":\"700\",\"color\":\"#222428\"},\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n            <h3 class=\"wp-block-heading\" style=\"color:#222428;margin-bottom:1rem;font-size:1.5rem;font-weight:700\">What Happens Next?</h3>\n            <!-- /wp:heading -->\n\n            <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.1rem\",\"lineHeight\":\"1.7\",\"color\":\"#6b7280\"}}} -->\n            <p style=\"color:#6b7280;font-size:1.1rem;line-height:1.7\">Once you submit the form, one of our expert realtors will contact you within 24 hours to discuss your needs, budget, and preferred locations. We\'ll then provide you with a curated list of properties that match your criteria and schedule virtual or in-person viewings at your convenience.</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column {\"width\":\"50%\"} -->\n        <div class=\"wp-block-column\" style=\"flex-basis:50%\">\n            <!-- wp:group {\"style\":{\"border\":{\"radius\":\"0.5rem\",\"width\":\"1px\"},\"spacing\":{\"padding\":{\"top\":\"3rem\",\"bottom\":\"3rem\",\"left\":\"3rem\",\"right\":\"3rem\"}},\"color\":{\"background\":\"#f4f5f8\"}},\"borderColor\":\"base-3\",\"layout\":{\"type\":\"constrained\"}} -->\n            <div class=\"wp-block-group has-border-color has-base-3-border-color has-background\" style=\"border-width:1px;border-radius:0.5rem;background-color:#f4f5f8;padding-top:3rem;padding-right:3rem;padding-bottom:3rem;padding-left:3rem\">\n                <!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.75rem\",\"fontWeight\":\"700\",\"color\":\"#222428\"},\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n                <h3 class=\"wp-block-heading has-text-align-center\" style=\"color:#222428;margin-bottom:1rem;font-size:1.75rem;font-weight:700\">Get Started Today</h3>\n                <!-- /wp:heading -->\n\n                <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1rem\",\"color\":\"#6b7280\"},\"spacing\":{\"margin\":{\"bottom\":\"2rem\"}}}} -->\n                <p class=\"has-text-align-center\" style=\"color:#6b7280;margin-bottom:2rem;font-size:1rem\">Fill out the form below and let us help you find your dream home in your new city.</p>\n                <!-- /wp:paragraph -->\n\n                <!-- wp:html -->\n                [forminator_form id=\"387\"]\n                <!-- /wp:html -->\n            </div>\n            <!-- /wp:group -->\n        </div>\n        <!-- /wp:column -->\n    </div>\n    <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"color\":{\"background\":\"#175873\"},\"spacing\":{\"padding\":{\"top\":\"3rem\",\"bottom\":\"3rem\"}}},\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-color has-text-color has-background\" style=\"background-color:#175873;padding-top:3rem;padding-bottom:3rem\">\n    <!-- wp:columns {\"align\":\"wide\"} -->\n    <div class=\"wp-block-columns alignwide\">\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">🏠 Property Search</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\",\"opacity\":\"0.9\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem;opacity:0.9\">Curated listings based on your preferences</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">📹 Virtual Tours</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\",\"opacity\":\"0.9\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem;opacity:0.9\">See properties from anywhere in the world</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">🤝 Full Support</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\",\"opacity\":\"0.9\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem;opacity:0.9\">From search to closing, we\'re with you</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n    </div>\n    <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->','Realtor Form','','inherit','closed','closed','','394-revision-v1','','','2025-07-24 00:14:12','2025-07-24 00:14:12','',394,'https://wp-smooth-demo.local/?p=5061',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (5062,1,'2025-07-24 00:14:40','2025-07-24 00:14:40','<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"8rem\",\"bottom\":\"var:preset|spacing|70\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"color\":{\"gradient\":\"linear-gradient(135deg,#175873 0%,#2c6c8a 100%)\"}},\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-color has-text-color has-background\" style=\"background:linear-gradient(135deg,#175873 0%,#2c6c8a 100%);margin-top:0;margin-bottom:0;padding-top:8rem;padding-bottom:var(--wp--preset--spacing--70)\">\n    <!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"clamp(2.5rem, 5vw, 4rem)\",\"fontWeight\":\"800\",\"lineHeight\":\"1.1\",\"textShadow\":\"2px 2px 4px rgba(0,0,0,0.3)\"},\"spacing\":{\"margin\":{\"bottom\":\"1.5rem\"}}}} -->\n    <h1 class=\"wp-block-heading has-text-align-center\" style=\"margin-bottom:1.5rem;font-size:clamp(2.5rem, 5vw, 4rem);font-weight:800;line-height:1.1;text-shadow:2px 2px 4px rgba(0,0,0,0.3)\">Get In Touch</h1>\n    <!-- /wp:heading -->\n\n    <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"400\",\"lineHeight\":\"1.6\",\"opacity\":\"0.9\"},\"spacing\":{\"margin\":{\"bottom\":\"2rem\"},\"padding\":{\"left\":\"1rem\",\"right\":\"1rem\"}}}} -->\n    <p class=\"has-text-align-center\" style=\"margin-bottom:2rem;padding-left:1rem;padding-right:1rem;font-size:1.25rem;font-weight:400;line-height:1.6;opacity:0.9\">Ready to start your smooth migration journey? We\'re here to help you every step of the way. Reach out to us and let\'s make your international move seamless.</p>\n    <!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"4rem\",\"bottom\":\"4rem\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:4rem;padding-bottom:4rem\">\n    <!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|60\"}}}} -->\n    <div class=\"wp-block-columns alignwide\">\n        <!-- wp:column {\"width\":\"40%\"} -->\n        <div class=\"wp-block-column\" style=\"flex-basis:40%\">\n            <!-- wp:heading {\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"2.5rem\",\"fontWeight\":\"700\",\"lineHeight\":\"1.2\",\"color\":\"#222428\"},\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n            <h2 class=\"wp-block-heading\" style=\"color:#222428;margin-bottom:1rem;font-size:2.5rem;font-weight:700;line-height:1.2\">Let\'s Talk</h2>\n            <!-- /wp:heading -->\n\n            <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.1rem\",\"lineHeight\":\"1.7\",\"color\":\"#6b7280\"},\"spacing\":{\"margin\":{\"bottom\":\"2rem\"}}}} -->\n            <p style=\"color:#6b7280;margin-bottom:2rem;font-size:1.1rem;line-height:1.7\">Whether you have questions about our services, need help planning your move, or want to discuss a custom solution, we\'re here to help. Our team of relocation experts is ready to provide personalized assistance for your unique situation.</p>\n            <!-- /wp:paragraph -->\n\n            <!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"2rem\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n            <div class=\"wp-block-group\" style=\"margin-bottom:2rem\">\n                <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\",\"fontWeight\":\"700\",\"color\":\"#175873\"},\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n                <h3 class=\"wp-block-heading\" style=\"color:#175873;margin-bottom:1rem;font-size:1.5rem;font-weight:700\">📞 Phone Support</h3>\n                <!-- /wp:heading -->\n                <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.1rem\",\"color\":\"#222428\"}}} -->\n                <p style=\"color:#222428;font-size:1.1rem\"><strong>+1 (555) 123-4567</strong><br>Monday - Friday: 9:00 AM - 6:00 PM EST<br>Saturday: 10:00 AM - 4:00 PM EST</p>\n                <!-- /wp:paragraph -->\n            </div>\n            <!-- /wp:group -->\n\n            <!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"2rem\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n            <div class=\"wp-block-group\" style=\"margin-bottom:2rem\">\n                <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\",\"fontWeight\":\"700\",\"color\":\"#175873\"},\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n                <h3 class=\"wp-block-heading\" style=\"color:#175873;margin-bottom:1rem;font-size:1.5rem;font-weight:700\">✉️ Email Support</h3>\n                <!-- /wp:heading -->\n                <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.1rem\",\"color\":\"#222428\"}}} -->\n                <p style=\"color:#222428;font-size:1.1rem\"><strong>hello@smoothmigration.com</strong><br>We typically respond within 2-4 hours during business days</p>\n                <!-- /wp:paragraph -->\n            </div>\n            <!-- /wp:group -->\n\n            <!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n            <div class=\"wp-block-group\">\n                <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.5rem\",\"fontWeight\":\"700\",\"color\":\"#175873\"},\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n                <h3 class=\"wp-block-heading\" style=\"color:#175873;margin-bottom:1rem;font-size:1.5rem;font-weight:700\">🕐 Response Time</h3>\n                <!-- /wp:heading -->\n                <!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.1rem\",\"color\":\"#6b7280\"}}} -->\n                <p style=\"color:#6b7280;font-size:1.1rem\">We pride ourselves on quick response times. Most inquiries are answered within 24 hours, and urgent matters are handled immediately.</p>\n                <!-- /wp:paragraph -->\n            </div>\n            <!-- /wp:group -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column {\"width\":\"60%\"} -->\n        <div class=\"wp-block-column\" style=\"flex-basis:60%\">\n            <!-- wp:group {\"style\":{\"border\":{\"radius\":\"0.5rem\",\"width\":\"1px\"},\"spacing\":{\"padding\":{\"top\":\"3rem\",\"bottom\":\"3rem\",\"left\":\"3rem\",\"right\":\"3rem\"}},\"color\":{\"background\":\"#f4f5f8\"}},\"borderColor\":\"base-3\",\"layout\":{\"type\":\"constrained\"}} -->\n            <div class=\"wp-block-group has-border-color has-base-3-border-color has-background\" style=\"border-width:1px;border-radius:0.5rem;background-color:#f4f5f8;padding-top:3rem;padding-right:3rem;padding-bottom:3rem;padding-left:3rem\">\n                <!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.75rem\",\"fontWeight\":\"700\",\"color\":\"#222428\"},\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n                <h3 class=\"wp-block-heading has-text-align-center\" style=\"color:#222428;margin-bottom:1rem;font-size:1.75rem;font-weight:700\">Send Us a Message</h3>\n                <!-- /wp:heading -->\n\n                <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1rem\",\"color\":\"#6b7280\"},\"spacing\":{\"margin\":{\"bottom\":\"2rem\"}}}} -->\n                <p class=\"has-text-align-center\" style=\"color:#6b7280;margin-bottom:2rem;font-size:1rem\">Fill out the form below and we\'ll get back to you as soon as possible.</p>\n                <!-- /wp:paragraph -->\n\n                <!-- wp:html -->\n                [forminator_form id=\"151\"]\n                <!-- /wp:html -->\n            </div>\n            <!-- /wp:group -->\n        </div>\n        <!-- /wp:column -->\n    </div>\n    <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"color\":{\"background\":\"#175873\"},\"spacing\":{\"padding\":{\"top\":\"3rem\",\"bottom\":\"3rem\"}}},\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-color has-text-color has-background\" style=\"background-color:#175873;padding-top:3rem;padding-bottom:3rem\">\n    <!-- wp:heading {\"textAlign\":\"center\",\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"2rem\",\"fontWeight\":\"700\"},\"spacing\":{\"margin\":{\"bottom\":\"2rem\"}}}} -->\n    <h2 class=\"wp-block-heading has-text-align-center\" style=\"margin-bottom:2rem;font-size:2rem;font-weight:700\">Ready to Get Started?</h2>\n    <!-- /wp:heading -->\n\n    <!-- wp:columns {\"align\":\"wide\"} -->\n    <div class=\"wp-block-columns alignwide\">\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">🌍 Global Services</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\",\"opacity\":\"0.9\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem;opacity:0.9\">We serve clients moving to 50+ countries worldwide</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">⚡ Fast Response</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\",\"opacity\":\"0.9\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem;opacity:0.9\">Quick replies and immediate assistance when you need it</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n\n        <!-- wp:column -->\n        <div class=\"wp-block-column\">\n            <!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n            <h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">🎯 Personalized</h4>\n            <!-- /wp:heading -->\n            <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\",\"opacity\":\"0.9\"}}} -->\n            <p class=\"has-text-align-center\" style=\"font-size:0.95rem;opacity:0.9\">Tailored solutions for your unique relocation needs</p>\n            <!-- /wp:paragraph -->\n        </div>\n        <!-- /wp:column -->\n    </div>\n    <!-- /wp:columns -->\n</div>\n<!-- /wp:group -->','Contact','','inherit','closed','closed','','75-revision-v1','','','2025-07-24 00:14:40','2025-07-24 00:14:40','',75,'https://wp-smooth-demo.local/?p=5062',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (5063,1,'2025-07-24 00:15:05','2025-07-24 00:15:05','<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"8rem\",\"bottom\":\"var:preset|spacing|70\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"color\":{\"gradient\":\"linear-gradient(135deg,#175873 0%,#2c6c8a 100%)\"}},\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-color has-text-color has-background\" style=\"background:linear-gradient(135deg,#175873 0%,#2c6c8a 100%);margin-top:0;margin-bottom:0;padding-top:8rem;padding-bottom:var(--wp--preset--spacing--70)\">\n    <!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"clamp(2.5rem, 5vw, 4rem)\",\"fontWeight\":\"800\",\"lineHeight\":\"1.1\",\"textShadow\":\"2px 2px 4px rgba(0,0,0,0.3)\"},\"spacing\":{\"margin\":{\"bottom\":\"1.5rem\"}}}} -->\n    <h1 class=\"wp-block-heading has-text-align-center\" style=\"margin-bottom:1.5rem;font-size:clamp(2.5rem, 5vw, 4rem);font-weight:800;line-height:1.1;text-shadow:2px 2px 4px rgba(0,0,0,0.3)\">Become a Partner</h1>\n    <!-- /wp:heading -->\n\n    <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"400\",\"lineHeight\":\"1.6\",\"opacity\":\"0.9\"},\"spacing\":{\"margin\":{\"bottom\":\"2rem\"},\"padding\":{\"left\":\"1rem\",\"right\":\"1rem\"}}}} -->\n    <p class=\"has-text-align-center\" style=\"margin-bottom:2rem;padding-left:1rem;padding-right:1rem;font-size:1.25rem;font-weight:400;line-height:1.6;opacity:0.9\">Join our global network of trusted service providers and help make international relocations smooth and successful. Together, we can serve clients worldwide.</p>\n    <!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"4rem\",\"bottom\":\"4rem\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:4rem;padding-bo