!-- /wp:list-item -->\n\n                <!-- wp:list-item -->\n                <li><strong style=\"color:#175873\">Partnership Benefits:</strong> Exclusive partner rates, priority support, and co-marketing opportunities.</li>\n                <!-- /wp:list-item -->\n            </ul>\n            <!-- /wp:list -->\n\n            <!-- wp:separator {\"style\":{\"spacing\":{\"margin\":{\"top\":\"3rem\",\"bottom\":\"3rem\"}},\"color\":{\"background\":\"#e0e0e0\"}}} -->\n            <hr class=\"wp-block-separator has-alpha-channel-opacity\" style=\"margin-top:3rem;margin-bottom:3rem;background-color:#e0e0e0\"/>\n            <!-- /wp:separator -->\n\n            <!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.75rem\",\"fontWeight\":\"700\",\"color\":\"#222428\"},\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n            <h3 class=\"wp-block-heading\" style=\"color:#222428;margin-bottom:1rem;font-size:1.75rem;font-weight:700\">Services We\'re Looking For</h3>\n            <!-- /wp:heading -->\n\n            <!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"var:preset|spacing|40\"}}}} -->\n            <div class=\"wp-block-columns\">\n                <!-- wp:column -->\n                <div class=\"wp-block-column\">\n                    <!-- wp:list {\"style\":{\"typography\":{\"fontSize\":\"1rem\",\"color\":\"#6b7280\"}}} -->\n                    <ul style=\"color:#6b7280;font-size:1rem\">\n                        <!-- wp:list-item -->\n                        <li>Real Estate Services</li>\n                        <!-- /wp:list-item -->\n                        <!-- wp:list-item -->\n                        <li>Banking & Financial</li>\n                        <!-- /wp:list-item -->\n                        <!-- wp:list-item -->\n                        <li>Immigration Law</li>\n                        <!-- /wp:list-item -->\n                        <!-- wp:list-item -->\n                        <li>Insurance Services</li>\