->\n<li>Educational Services</li>\n<!-- /wp:list-item -->\n                        \n<!-- wp:list-item -->\n<li>Pet Relocation</li>\n<!-- /wp:list-item -->\n                    </ul>\n<!-- /wp:list --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:group {\"style\":{\"border\":{\"radius\":\"0.5rem\",\"width\":\"1px\"},\"spacing\":{\"padding\":{\"top\":\"3rem\",\"bottom\":\"3rem\",\"left\":\"3rem\",\"right\":\"3rem\"}},\"color\":{\"background\":\"#f4f5f8\"}},\"borderColor\":\"base-3\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-border-color has-base-3-border-color has-background\" style=\"border-width:1px;border-radius:0.5rem;background-color:#f4f5f8;padding-top:3rem;padding-right:3rem;padding-bottom:3rem;padding-left:3rem\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.75rem\",\"fontWeight\":\"700\",\"color\":\"#222428\"},\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"color:#222428;margin-bottom:1rem;font-size:1.75rem;font-weight:700\">Apply to Partner</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1rem\",\"color\":\"#6b7280\"},\"spacing\":{\"margin\":{\"bottom\":\"2rem\"}}}} -->\n<p class=\"has-text-align-center\" style=\"margin-bottom:2rem;font-size:1rem\"><p class=\"has-text-align-center\" style=\"color:#6b7280;margin-bottom:2rem;font-size:1rem\">Ready to join our network? Fill out the partnership application below and we\'ll be in touch within 48 hours.</p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:html -->\n[forminator_form id=\"5051\"]\n<!-- /wp:html --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"color\":{\"background\":\"#175873\"},\"spacing\":{\"padding\":{\"top\":\"3rem\",\"bottom\":\"3rem\"}}},\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-white-color has-text-color has-background\" style=\"background-color:#175873;padding-top:3rem;padding-bottom:3rem\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"2rem\",\"fontWeight\":\"700\"},\"spacing\":{\"margin\":{\"bottom\":\"2rem\"}}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\" style=\"margin-bottom:2rem;font-size:2rem;font-weight:700\">Partnership Process</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">1️⃣ Application</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\",\"opacity\":\"0.9\"}}} -->\n<p class=\"has-text-align-center\" style=\"font-size:0.95rem\"><p class=\"has-text-align-center\" style=\"font-size:0.95rem;opacity:0.9\">Submit your partnership application with business details</p></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">2️⃣ Review</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\",\"opacity\":\"0.9\"}}} -->\n<p class=\"has-text-align-center\" style=\"font-size:0.95rem\"><p class=\"has-text-align-center\" style=\"font-size:0.95rem;opacity:0.9\">We review your credentials and service offerings</p></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\",\"fontWeight\":\"600\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\" style=\"font-size:1.25rem;font-weight:600\">3️⃣ Onboarding</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\",\"opacity\":\"0.9\"}}} -->\n<p class=\"has-text-align-center\" style=\"font-size:0.95rem\"><p class=\"has-text-align-center\" style=\"font-size:0.95rem;opacity:0.9\">Welcome to the network! Start receiving referrals</p></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->','Become a Partner','','inherit','closed','closed','','5052-autosave-v1','','','2025-07-24 00:28:11','2025-07-24 00:28:11','',5052,'https://stormy-support.localsite.io/?p=5065',0,'revision','',0);
